/// The merged hand-over pass of the structured engine (GOAL #2394 — the
/// `merged` mode of `selectCompactionMode`). ONE model call over the S0
/// prefix (the last main request as sent) plus the appended instruction
/// answers BOTH questions of a run — which records outside the fold range
/// are safe to hide, and the transfer text for the range — and the engine
/// DISPOSES over the answer:
///
/// - hide aliases resolve against the SNAPSHOT index (never a fresh
///   ledger — aliases drift under windowed storage and hard caps) and are
///   validated against the fresh projection (`disposeHidePicks`: snap to
///   pair groups, user turns never hidden, tail/pins, covered/in-range,
///   fold records);
/// - the transfer text must carry the mandatory `## Open User Requests`
///   section with every mechanical ask line verbatim (D2/#81), and is
///   persisted through the gh-2103 sanitizer with the S0 origin evidence
///   and the pinned lines protected;
/// - the hidden range rides ONE record (`labels`, `consolidated: true`)
///   and the checkpoint rides its own record (`layout: tail`).
///
/// No fallback: a failed call, an unusable reply or a failed check appends
/// NOTHING (I5) and reports loudly — the engine never changes (I9). No
/// second call on the new projection (E21): residual pressure is the next
/// prompt's pre-flight business (the host's hysteresis keeps the band
/// quiet for N turns).
part of 'engine.dart';

/// The merged hand-over pass's report metrics (GOAL #2394 AC14): the mode,
/// the bucket, the REAL round-trip count and the hide list's buckets. A
/// provider that reports no usage leaves [cacheHitRatio] `null` — never a
/// fake zero (gh-2097).
final class HandOverPassMetrics {
  /// Creates the metrics.
  const HandOverPassMetrics({
    required this.bucket,
    required this.calls,
    required this.nudges,
    required this.budgetRetries,
    required this.hideList,
    required this.transfer,
    this.cacheHitRatio,
  });

  /// The mode the run chose — always `merged` for this pass.
  static const String mode = 'merged';

  /// `warm` while the S0 bucket's TTL held at call time, else `cold` (a
  /// signal, never a condition — E11).
  final String bucket;

  /// Real round-trips the logical call consumed (nudge and budget retry
  /// included).
  final int calls;

  /// Nudge round-trips (0 or 1).
  final int nudges;

  /// Output-budget retries (0 or 1).
  final int budgetRetries;

  /// The hide list's buckets as the report renders them
  /// (`HandOverDisposeVerdict.render`); `none` when the reply proposed
  /// nothing.
  final String hideList;

  /// `text` when a transfer text was persisted, `none` for a hide-only
  /// reply (E5).
  final String transfer;

  /// Share of input tokens served from cache across the call, `null`
  /// when the provider reported no usage.
  final double? cacheHitRatio;

  /// The one-line report form: `merged · bucket warm · calls 1 · cache
  /// 92% · hide list 2 snapped · nudges 0 · budget retries 0 · transfer
  /// text` (the cache term is omitted without usage).
  String render() => [
    mode,
    'bucket $bucket',
    'calls $calls',
    if (cacheHitRatio != null) 'cache ${(cacheHitRatio! * 100).round()}%',
    'hide list ${hideList == '' ? 'none' : hideList}',
    'nudges $nudges',
    'budget retries $budgetRetries',
    'transfer $transfer',
  ].join(' · ');
}

/// The pass's gate + fold range: `null` when the run ends here with the
/// verdict `true` — an honest decline ([StructuredCompactor.exitReason]
/// names it) — or `false` after a ladder kill. The gate is waived by
/// `force` or by the host's soft arm ([softTriggered], AC11).
Future<({_LedgerView view, _CkptRange range})?> _handOverRange(
  StructuredCompactor c, {
  required int trigger,
  required bool force,
  required bool softTriggered,
}) async {
  final before = c._requestTokens();
  if (!force && !softTriggered && before <= trigger) {
    c.exitReason = 'basis $before below trigger $trigger (hand-over gate)';
    return null;
  }
  if (c._ladderTerminated) return null;
  final view = await c._buildView();
  if (view == null) {
    c.exitReason = 'projection view unavailable (hand-over gate)';
    return null;
  }
  final range = await c._pickCheckpointRange(
    view: view,
    wholeWorldDeclines: false,
  );
  if (range == null) {
    c.exitReason =
        'no foldable range below the keep-recent boundary (hand-over gate)';
  }
  return range == null ? null : (view: view, range: range);
}

/// ONE logical call = at most three round-trips (nudge, budget retry)
/// under the tripled attempt budget; the budget kill is the factory's
/// outcome (issue #515) and must not dissolve into the failure-safety
/// false — it rethrows.
Future<HandOverCallResult> _callHandOver(
  StructuredCompactor c, {
  required HandOverCall handOver,
  required RequestSnapshot snapshot,
  required String instruction,
}) {
  final budget = c.attemptBudget * 3;
  return handOver(
    snapshot.toContext(extraMessages: [UserMessage.text(instruction)]),
    cancelToken: c._effectiveToken,
  ).timeout(
    budget,
    onTimeout: () {
      final timeout = c._budgetTimeout('hand-over call', budget);
      c.budgetSource?.cancel(timeout);
      throw timeout;
    },
  );
}

/// The reply's transfer text — sanitized (think blocks and echo tags
/// out, the gh-2103 belt with the S0 origin evidence, the pinned lines
/// protected) and verified against the mechanical asks. `null` for a
/// hide-only reply (E5); [failed] when the check failed (nothing may be
/// appended, the pass reported its failure through [fail]).
({String? transfer, bool failed}) _handOverTransfer(
  StructuredCompactor c, {
  required HandOverReply reply,
  required RequestSnapshot snapshot,
  required List<String> openAsks,
  required void Function(Object error) fail,
}) {
  final raw = reply.transfer;
  if (raw == null || raw.trim().isEmpty) return (transfer: null, failed: false);
  var transfer = sanitizeSummary(
    stripRecordTags(stripThinkBlocks(raw)),
    protectedLines: c.pinnedLines,
    origins: SummaryOriginEvidence(snapshot.messages),
  ).text.trim();
  if (transfer.isEmpty) return (transfer: null, failed: false);
  final asks = verifyOpenUserRequests(transfer, openAsks);
  if (!asks.heading || asks.missing.isNotEmpty) {
    fail(CompactionException(_handOverAskFailure(asks)));
    return (transfer: null, failed: true);
  }
  return (transfer: transfer, failed: false);
}

String _handOverAskFailure(({bool heading, List<String> missing}) asks) =>
    !asks.heading
    ? 'hand-over transfer carries no `## Open User Requests` '
          'section — the sanitizer belt cannot grade it; nothing '
          'was appended'
    : 'hand-over transfer dropped ${asks.missing.length} '
          'open user request(s) from <open-user-requests>; '
          'nothing was appended';

/// Disposes the reply's hide list against the FRESH projection (snap to
/// pair groups, user turns never hidden, tail/pins, covered/in-range,
/// fold records — the SNAPSHOT index resolves the aliases).
HandOverDisposeVerdict _handOverVerdict(
  StructuredCompactor c, {
  required HandOverReply reply,
  required RequestSnapshot snapshot,
  required _LedgerView view,
  required _CkptRange range,
}) {
  final foldFrom = view.seqs.seqOf(range.firstRecordId) ?? 0;
  final foldTo = view.seqs.seqOf(range.lastRecordId) ?? foldFrom;
  return disposeHidePicks(
    picks: reply.picks,
    snapshotIndex: snapshot.seqMap.index,
    ledger: view.ledger,
    state: view.state,
    protectedTail: protectedTailIds(view.ledger, c.protectLastN),
    foldFromSeq: foldFrom,
    foldToSeq: foldTo,
    inRangeSeqs: {
      for (final id in range.coveredRecordIds) ?view.seqs.seqOf(id),
    },
  );
}

/// Appends the run's records — the consolidated hidden range first, then
/// the tail-layout checkpoint. `false` after a ladder kill (written-but-
/// unprojected stops here; resume replays it).
Future<bool> _appendHandOverRecords(
  StructuredCompactor c, {
  required HandOverDisposeVerdict verdict,
  required _CkptRange range,
  required String? transfer,
}) async {
  if (verdict.recordIds.isNotEmpty) {
    await c.session.appendHiddenRange(
      recordIds: verdict.recordIds,
      labels: verdict.labels,
      consolidated: true,
    );
    if (c._ladderTerminated) return false;
  }
  if (transfer == null) return true;
  await c.session.appendCompactCheckpoint(
    firstRecordId: range.firstRecordId,
    lastRecordId: range.lastRecordId,
    text: transfer,
    coversRecordIds: range.coveredRecordIds,
    flattenedRecordIds: [
      for (final ckpt in c._flattenForDepthCap(range)) ckpt.id,
    ],
    layout: compactCheckpointLayoutTail,
  );
  return !c._ladderTerminated;
}

int _summarizedCount(_CkptRange range) {
  var count = 0;
  for (final id in range.coveredRecordIds) {
    final seq = range.seqs.seqOf(id);
    if (seq != null && range.seqs.recordAt(seq) is MessageRecord) count++;
  }
  return count;
}

HandOverReply _handOverReply(AssistantMessage response) => parseHandOverReply(
  [
    for (final block in response.content)
      if (block is TextContent) block.text,
  ].join('\n'),
);

StructuredCompactionPass _handOverPassReport(
  StructuredCompactor c, {
  required HandOverCallResult result,
  required HandOverDisposeVerdict verdict,
  required RequestSnapshot snapshot,
  required int before,
  required int after,
  required String? transfer,
  required int summarizedCount,
  required int durationMs,
  required CompactionUsageTotals? usage,
}) => StructuredCompactionPass(
  kind: 'hand-over',
  pass: ++c._pass,
  tokensBefore: before,
  tokensAfter: after,
  ok: true,
  judgeCalls: result.calls,
  hiddenCount: verdict.recordIds.length,
  summarizedCount: summarizedCount,
  summary: transfer,
  basisReadTokens: c._basisFlip(before, after),
  durationMs: durationMs,
  usage: usage,
  handOver: HandOverPassMetrics(
    bucket: snapshot.bucket(),
    calls: result.calls,
    nudges: result.nudges,
    budgetRetries: result.budgetRetries,
    hideList: verdict.render(),
    transfer: transfer == null ? 'none' : 'text',
    cacheHitRatio: result.cacheHitRatio,
  ),
);

/// Runs the merged hand-over pass for [c]. Returns whether the run's
/// verdict stands: `true` when the pass appended (or honestly declined
/// through [StructuredCompactor.exitReason]), `false` only on a failure
/// — a failed call, an unusable reply, a failed ask check, a ladder kill.
/// [softTriggered] waives the hard trigger gate: the host measured the
/// post-run soft line (AC11) and armed this run itself.
Future<bool> _runHandOverPass(
  StructuredCompactor c, {
  required int trigger,
  required bool force,
  required bool softTriggered,
}) async {
  final handOver = c.handOver!;
  final snapshot = c.requestSnapshot!;
  final before = c._requestTokens();
  final armed = await _handOverRange(
    c,
    trigger: trigger,
    force: force,
    softTriggered: softTriggered,
  );
  if (armed == null) return !c._ladderTerminated;
  if (c._ladderTerminated) return false;
  final watch = Stopwatch()..start();
  final usageBefore = c.usage?.snapshot();
  final openAsks = _handOverOpenAsks(armed.range);
  final instruction = _handOverInstruction(
    c,
    view: armed.view,
    range: armed.range,
    openAsks: openAsks,
    contextTokens: before,
  );
  if (c._ladderTerminated) return false;
  final HandOverCallResult result;
  try {
    result = await _callHandOver(
      c,
      handOver: handOver,
      snapshot: snapshot,
      instruction: instruction,
    );
  } on TimeoutException {
    rethrow;
  }
  // #2258: the verdict may have landed while the call ran — nothing is
  // appended, refreshed or reported after it.
  if (c._ladderTerminated) return false;
  void fail(Object error) => c.hooks?.onPass(
    StructuredCompactionPass(
      kind: 'hand-over',
      pass: ++c._pass,
      tokensBefore: before,
      tokensAfter: before,
      ok: false,
      error: error,
      durationMs: watch.elapsedMilliseconds,
      usage: c._usageDelta(usageBefore),
    ),
  );
  if (!result.ok) {
    fail(
      result.failure ??
          const CompactionException('hand-over call returned no answer'),
    );
    return false;
  }
  final reply = _handOverReply(result.response!);
  final transfer = _handOverTransfer(
    c,
    reply: reply,
    snapshot: snapshot,
    openAsks: openAsks,
    fail: fail,
  );
  if (transfer.failed) return false;
  final verdict = _handOverVerdict(
    c,
    reply: reply,
    snapshot: snapshot,
    view: armed.view,
    range: armed.range,
  );
  if (!await _appendHandOverRecords(
    c,
    verdict: verdict,
    range: armed.range,
    transfer: transfer.transfer,
  )) {
    return false;
  }
  final after = await c._refreshState();
  c.hooks?.onPass(
    _handOverPassReport(
      c,
      result: result,
      verdict: verdict,
      snapshot: snapshot,
      before: before,
      after: after,
      transfer: transfer.transfer,
      summarizedCount: transfer.transfer == null
          ? 0
          : _summarizedCount(armed.range),
      durationMs: watch.elapsedMilliseconds,
      usage: c._usageDelta(usageBefore),
    ),
  );
  return true;
}

/// The mechanical `<open-user-requests>` ground truth of the fold range:
/// the same #81 extraction the standalone checkpoint prompt rides.
List<String> _handOverOpenAsks(_CkptRange range) => userRequestCandidateLines(
  [
    for (final record in range.visible)
      if (range.coveredRecordIds.contains(record.id) &&
          record is MessageRecord &&
          record.message.role == 'user')
        record.message,
  ],
  recordIds: [
    for (final record in range.visible)
      if (range.coveredRecordIds.contains(record.id) &&
          record is MessageRecord &&
          record.message.role == 'user')
        record.id,
  ],
);

/// The appended instruction (AC3/AC6): the prompt template with the
/// pressure, the fold range aliases, the tag rule, the mechanical asks,
/// the pinned-operative block and the depth-cap `<folded-checkpoint>`
/// blocks (sanitized — older persisted checkpoints re-enter a prompt
/// healed, issue #1131; pins inside them protected, gh-1409).
String _handOverInstruction(
  StructuredCompactor c, {
  required _LedgerView view,
  required _CkptRange range,
  required List<String> openAsks,
  required int contextTokens,
}) {
  final folded = [
    for (final ckpt in c._flattenForDepthCap(range))
      '<folded-checkpoint>\n'
          '${sanitizeSummary(ckpt.text, protectedLines: c.pinnedLines).text}'
          '\n</folded-checkpoint>',
  ];
  return renderHandOverInstruction(
    template: c.handOverPrompt,
    contextTokens: contextTokens,
    windowTokens: c.window,
    foldFrom: view.seqs.seqOf(range.firstRecordId) ?? 0,
    foldTo: view.seqs.seqOf(range.lastRecordId) ?? 0,
    openUserRequests: openAsks,
    pinnedOperative: c.pinnedOperativeBlock,
    foldedCheckpoints: folded.isEmpty ? null : folded.join('\n'),
  );
}

/// The hand-over reply protocol of the merged compaction call (GOAL
/// #2394): the instruction renderer, the reply parser and the hide-label
/// sanitizer. Pure functions over text — no IO, no provider.
///
/// One call reads the last main request as sent (S0 — every record tagged
/// `m<N>`) plus ONE appended instruction ([renderHandOverInstruction]);
/// the reply is a hide list followed by `-` and the hand-over text
/// ([parseHandOverReply]). The model PROPOSES — the engine disposes (see
/// `hand_over_dispose.dart`); every label the model writes passes
/// [sanitizeHideLabel] before it can reach a marker.
library;

import '../summary_sanitizer.dart';

/// One hide proposal: the inclusive alias range `from`..`to` on the S0
/// epoch plus the model's raw label text (unsanitized).
final class HandOverHidePick {
  /// Creates a pick.
  const HandOverHidePick({
    required this.from,
    required this.to,
    required this.rawLabel,
  });

  /// The first alias of the range.
  final int from;

  /// The last alias of the range (equal to [from] for a single record).
  final int to;

  /// The label exactly as the model wrote it (empty when none).
  final String rawLabel;
}

/// A parsed hand-over reply.
final class HandOverReply {
  /// Creates a reply.
  const HandOverReply({
    required this.picks,
    required this.transfer,
    required this.ignoredLines,
  });

  /// The hide proposals in reply order, deduplicated.
  final List<HandOverHidePick> picks;

  /// The hand-over text after the `-` separator; `null` when the reply
  /// carried no text (hide-only, E5) or was empty.
  final String? transfer;

  /// Reply lines inside the hide prefix that named no usable alias
  /// (garbage or inverted ranges) — a count for the run log, never
  /// content.
  final int ignoredLines;

  /// Whether the reply proposed a hide-only run (no transfer text).
  bool get hideOnly => picks.isNotEmpty && transfer == null;
}

final RegExp _thinkBlocks = RegExp(
  r'<think>.*?</think>',
  dotAll: true,
  caseSensitive: false,
);
final RegExp _thinkOpenEnded = RegExp(
  r'<think>.*$',
  dotAll: true,
  caseSensitive: false,
);
final RegExp _zeroWidth = RegExp(r'[\u200B\u200C\u200D\u2060\uFEFF]');

/// Normalizes a reply's encoding noise (E1): BOM, zero-width characters
/// and CRLF line endings never reach the parser.
String normalizeReplyText(String text) => text
    .replaceAll(_zeroWidth, '')
    .replaceAll('\r\n', '\n')
    .replaceAll('\r', '\n');

/// Removes `<think>…</think>` blocks — and an unclosed `<think>` through
/// the end of the text — BEFORE parsing or persisting (E3): reasoning that
/// leaked into the text channel is never a hide id, never a transfer.
String stripThinkBlocks(String text) =>
    text.replaceAll(_thinkBlocks, '').replaceAll(_thinkOpenEnded, '');

// `(?![0-9])` binds the alias: an over-long digit run is not an alias.
final RegExp _rangeLine = RegExp(
  r'^\s*m?(\d{1,9})(?![0-9])\s*-\s*(\d{1,9})(?![0-9])(?:\s+-\s*|\s+)?(.*?)\s*$',
);
final RegExp _singleLine = RegExp(
  r'^\s*m?(\d{1,9})(?![0-9])(?:\s+-\s*|\s+)?(.*?)\s*$',
);
final RegExp _separatorLine = RegExp(r'^-{2,}$');

/// A hide-list range wider than this is a degenerate echo (the judge
/// parser's bound) and names nothing.
const int _maxRangeSpan = 10000;

/// Parses the model's hand-over reply (AC5).
///
/// The hide list is the MAXIMAL PREFIX of lines of the shape `N`, `N-M`
/// (inclusive range) plus an optional ` - ` / whitespace and a label:
/// - an inverted or over-long range is ignored (counted in
///   [HandOverReply.ignoredLines]); duplicates collapse (E2);
/// - a line of dashes (`-`, `---`) ends the list; the separator is
///   OPTIONAL — the first non-id, non-blank line after the list starts
///   the transfer (blank lines never end it);
/// - a FIRST line that is not an id and not the separator means NO hides
///   and the whole text is the transfer (the skeleton example `NN-NN`
///   returned verbatim lands here — E29);
/// - no text after the list → [HandOverReply.transfer] is `null`
///   (hide-only, E5).
HandOverReply parseHandOverReply(String text) {
  final normalized = stripThinkBlocks(normalizeReplyText(text)).trim();
  if (normalized.isEmpty) {
    return const HandOverReply(picks: [], transfer: null, ignoredLines: 0);
  }
  final lines = normalized.split('\n');
  final picks = <HandOverHidePick>[];
  final seen = <String>{};
  var ignored = 0;
  var index = 0;
  // Blank lines never end the list (a model often pads before the `-`);
  // the first non-blank line that names no alias does.
  while (index < lines.length) {
    final parsed = _hideListLine(lines[index], seen);
    picks.addAll([?parsed.pick]);
    if (parsed.ignored) {
      ignored++;
    }
    if (parsed.consumed) {
      index++;
    }
    if (parsed.ends) {
      break;
    }
  }
  if (index == 0) {
    // Not an id line and not a separator: no hides, whole text = transfer.
    return HandOverReply(
      picks: const [],
      transfer: normalized,
      ignoredLines: 0,
    );
  }
  final transfer = lines.sublist(index).join('\n').trim();
  return HandOverReply(
    picks: picks,
    transfer: transfer.isEmpty ? null : transfer,
    ignoredLines: ignored,
  );
}

/// One hide-list line: [pick] names an alias (deduplicated through
/// [seen]), [ignored] is an id line naming nothing usable, [ends] stops
/// the list (the separator, or a line that is no id at all), and
/// [consumed] says whether the line belongs to the list (a non-id line
/// starts the transfer itself).
({HandOverHidePick? pick, bool ignored, bool ends, bool consumed})
_hideListLine(String line, Set<String> seen) {
  final trimmed = line.trim();
  if (trimmed.isEmpty) {
    return (pick: null, ignored: false, ends: false, consumed: true);
  }
  if (trimmed == '-' || _separatorLine.hasMatch(trimmed)) {
    return (pick: null, ignored: false, ends: true, consumed: true);
  }
  final range = _rangeLine.firstMatch(line);
  final single = range == null ? _singleLine.firstMatch(line) : null;
  if (range == null && single == null) {
    return (pick: null, ignored: false, ends: true, consumed: false);
  }
  final parsed = _aliasLine(range ?? single!, isRange: range != null);
  final key = parsed.pick == null
      ? ''
      : '${parsed.pick!.from}-${parsed.pick!.to}';
  if (parsed.pick != null && !seen.add(key)) {
    return (pick: null, ignored: false, ends: false, consumed: true);
  }
  return (
    pick: parsed.pick,
    ignored: parsed.ignored,
    ends: false,
    consumed: true,
  );
}

/// An id line's pick: an inverted or over-long range is [ignored]
/// (counted, never content).
({HandOverHidePick? pick, bool ignored}) _aliasLine(
  RegExpMatch match, {
  required bool isRange,
}) {
  final from = int.parse(match.group(1)!);
  final to = isRange ? int.parse(match.group(2)!) : from;
  if (from <= 0 || to < from || to - from >= _maxRangeSpan) {
    return (pick: null, ignored: true);
  }
  return (
    pick: HandOverHidePick(
      from: from,
      to: to,
      rawLabel: (match.group(isRange ? 3 : 2) ?? '').trim(),
    ),
    ignored: false,
  );
}

final RegExp _labelLead = RegExp(r'^[-–—:]+\s*');
final RegExp _whitespaceRun = RegExp(r'\s+');
final RegExp _brackets = RegExp(r'[\[\]]');
final RegExp _numericEcho = RegExp(r'^m?\d+(?:-\d+)?(?:\s+m?\d+(?:-\d+)?)*$');

// Word boundaries that understand Cyrillic too: `\b` is ASCII-only.
const String _notWord = r'(?<![A-Za-z0-9А-Яа-яЁё])';
const String _notWordAfter = r'(?![A-Za-z0-9А-Яа-яЁё])';
final RegExp _secondPersonLabel = RegExp(
  '$_notWord(?:you|your|yours|yourself|u|ur|ты|тебя|твой|вы|вас|ваш|ваша|ваше|ваши|вам)'
  '$_notWordAfter',
  caseSensitive: false,
);
final RegExp _imperativeLabel = RegExp(
  '$_notWord(?:must|should|do not|don\'t|always|never|required|'
  r'обязательно|нужно|должен|должна|должно|запрещено|всегда|никогда)'
  '$_notWordAfter',
  caseSensitive: false,
);

/// The label budget (D3): one line, at most this many characters…
const int hideLabelMaxChars = 48;

/// …and at most this many words.
const int hideLabelMaxWords = 6;

/// Sanitizes a model-written hide label (D3/E35) into text safe to render
/// in every later request, or `null` (the marker then carries no label):
/// one whitespace-collapsed line without `[]`, ≤ [hideLabelMaxChars]
/// characters and ≤ [hideLabelMaxWords] words, no second person, no
/// imperative/imperative-shaped markers, no digits-only range echo — and
/// unchanged through the summary sanitizer's ephemeral arm (a label the
/// sanitizer would rewrite is not a label). NEVER stored as a message.
String? sanitizeHideLabel(String raw) {
  var label = raw
      .trim()
      .replaceFirst(_labelLead, '')
      .replaceAll(_whitespaceRun, ' ')
      .trim();
  if (label.isEmpty || label == '-') return null;
  if (_brackets.hasMatch(label)) return null;
  if (label.length > hideLabelMaxChars) return null;
  if (label.split(' ').length > hideLabelMaxWords) return null;
  if (_numericEcho.hasMatch(label)) return null;
  if (_secondPersonLabel.hasMatch(label)) return null;
  if (_imperativeLabel.hasMatch(label)) return null;
  if (sanitizeSummary(label).text != label) return null;
  return label;
}

final RegExp _placeholder = RegExp(r'\{\{(\w+)\}\}');

/// Renders the hand-over instruction from the prompt template (D13 —
/// `prompts.g.dart` carries no templating, the `{{…}}` tokens are
/// substituted here, at the call site). Deterministic: same inputs, same
/// text; an unknown token is left verbatim so a prompt edit naming a new
/// placeholder surfaces in the output instead of vanishing.
String renderHandOverInstruction({
  required String template,
  required int contextTokens,
  required int windowTokens,
  required int foldFrom,
  required int foldTo,
  List<String> openUserRequests = const [],
  String? pinnedOperative,
  String? foldedCheckpoints,
}) {
  final values = <String, String>{
    'context_tokens': '$contextTokens',
    'window_tokens': '$windowTokens',
    'fold_from': '$foldFrom',
    'fold_to': '$foldTo',
    'open_user_requests': openUserRequests.isEmpty
        ? 'none'
        : openUserRequests.join('\n'),
    'pinned_operative': pinnedOperative ?? '',
    'folded_checkpoints': foldedCheckpoints ?? '',
  };
  return template
      .replaceAllMapped(_placeholder, (match) => values[match[1]] ?? match[0]!)
      .trimRight();
}

final RegExp _userIntentHeading = RegExp(
  r'^(?:#{1,6}\s*)?(?:open user requests\b|open asks\b\s*:)',
  multiLine: true,
  caseSensitive: false,
);
final RegExp _askPointer = RegExp(r'^\s*-\s*\[[^\]]*\]\s*');

/// The verdict of the mechanical open-asks check (D2/#81).
typedef OpenUserRequestsVerdict = ({
  /// Whether the transfer carries the mandatory `## Open User Requests`
  /// (or `open asks:`) heading — without it the sanitizer belt cannot
  /// run, so the run FAILS.
  bool heading,

  /// Every `<open-user-requests>` line whose text (after the pointer,
  /// whitespace-flattened) is not present VERBATIM in the transfer.
  List<String> missing,
});

/// Verifies the hand-over text against the engine's mechanical
/// `<open-user-requests>` block (AC6): the heading must be present and
/// every ask line must survive verbatim; otherwise the run fails and
/// nothing is appended (E36).
OpenUserRequestsVerdict verifyOpenUserRequests(
  String transfer,
  List<String> askLines,
) {
  final flat = transfer.replaceAll(_whitespaceRun, ' ');
  final missing = <String>[];
  for (final line in askLines) {
    final text = line.replaceFirst(_askPointer, '').trim();
    if (text.isEmpty) continue;
    if (!flat.contains(text.replaceAll(_whitespaceRun, ' '))) {
      missing.add(text);
    }
  }
  return (heading: _userIntentHeading.hasMatch(transfer), missing: missing);
}

/// The engine DISPOSES over the model's hide proposals (GOAL #2394 AC7):
/// every alias the reply names resolves against the S0 SNAPSHOT index
/// (never a fresh ledger — aliases drift under windowed storage and hard
/// caps, ✗C/D7), the record is then validated against the FRESH projection
/// with the judge-era `validateHidePicks` semantics (snap OUTWARD to whole
/// pair groups, protected tail, pinned expansions, `·exempt` user turns),
/// plus the merged call's new rejections:
///
/// - `U` unknown — the alias names nothing on the frozen epoch index
///   (hallucinated, the live edge, beyond the index);
/// - `X` exempt — a real user turn is never hidden, whatever the model
///   wrote (F8/F9/E9);
/// - `T` tail/pin — the protected live edge or a pinned expansion;
/// - `C` covered/in-range — already hidden, checkpoint-covered, or inside
///   the fold range fixed before the call (moot: the checkpoint supersedes);
/// - `F` fold record — an old checkpoint / classic summary / branch
///   summary: hiding it would unfold its range and GROW pressure (E28);
/// - `S` snapped — the pick (plus its whole pair group) is hidden.
///
/// Pure — no IO; the engine appends the verdict's ids.
library;

import '../../session/session_record.dart';
import '../../context.dart';
import 'hand_over.dart';
import 'ledger.dart';
import 'projection.dart';

/// Where one hide proposal landed.
enum HidePickBucket {
  /// Hidden (snapped outward to the whole pair group).
  snapped,

  /// Unknown alias on the snapshot index.
  unknown,

  /// A real user turn.
  exempt,

  /// Protected tail or a pinned expansion.
  tail,

  /// Already hidden/covered or inside the fold range (moot).
  covered,

  /// A fold record (checkpoint / classic summary / branch summary).
  foldRecord,
}

/// The dispose verdict over one hand-over reply's hide list.
final class HandOverDisposeVerdict {
  /// Creates a verdict.
  const HandOverDisposeVerdict({
    required this.recordIds,
    required this.labels,
    required this.counts,
  });

  /// The stable record ids to hide — every surviving pick's WHOLE pair
  /// group, deduplicated, sorted.
  final List<String> recordIds;

  /// Sanitized label per CARRIER record id (the group's first record in
  /// file order); a pick whose label failed sanitization carries none.
  final Map<String, String> labels;

  /// Picks per bucket (every pick lands in exactly one).
  final Map<HidePickBucket, int> counts;

  /// Picks that produced ids.
  int get snapped => counts[HidePickBucket.snapped] ?? 0;

  /// Picks that named nothing on the snapshot index.
  int get unknown => counts[HidePickBucket.unknown] ?? 0;

  /// Picks that named a real user turn.
  int get exempt => counts[HidePickBucket.exempt] ?? 0;

  /// Picks that named the protected tail or a pinned expansion.
  int get tail => counts[HidePickBucket.tail] ?? 0;

  /// Picks that were moot (hidden / covered / inside the fold range).
  int get covered => counts[HidePickBucket.covered] ?? 0;

  /// Picks that named a fold record.
  int get foldRecord => counts[HidePickBucket.foldRecord] ?? 0;

  /// The report's hide-list line: `P → S snapped · U unknown · …` with
  /// the zero buckets omitted.
  String render() {
    final parts = <String>[
      '$snapped snapped',
      if (unknown > 0) '$unknown unknown',
      if (exempt > 0) '$exempt exempt',
      if (tail > 0) '$tail tail/pin',
      if (covered > 0) '$covered covered/in-range',
      if (foldRecord > 0) '$foldRecord fold-record',
    ];
    return parts.join(' · ');
  }
}

/// Disposes the reply's [picks].
///
/// [snapshotIndex] is the S0 epoch's `RecordSeqIndex` (alias → record);
/// [ledger] the FRESH view's ledger (pair groups, `exempt`), [state] the
/// fresh structured view (hidden / covered / pinned), [protectedTail] the
/// live-edge ids, [foldFromSeq]..[foldToSeq] the fold range fixed before
/// the call — or, when the engine knows the exact members, [inRangeSeqs]
/// (a pinned record INSIDE the span is not a member: hiding it is legal,
/// so the span alone would mis-bucket it as moot). Never throws: a pick
/// that names nothing lands in `U`.
HandOverDisposeVerdict disposeHidePicks({
  required List<HandOverHidePick> picks,
  required RecordSeqIndex snapshotIndex,
  required ContextLedger ledger,
  required StructuredViewState state,
  required Set<String> protectedTail,
  required int foldFromSeq,
  required int foldToSeq,
  Set<int>? inRangeSeqs,
}) {
  final entryById = {for (final entry in ledger.entries) entry.recordId: entry};
  final counts = {for (final bucket in HidePickBucket.values) bucket: 0};
  final ids = <String>{};
  final labels = <String, String>{};
  for (final pick in picks) {
    final resolved = <SessionRecord>[
      // Aliases beyond the frozen index resolve to nothing (`null`).
      for (var seq = pick.from; seq <= pick.to; seq++)
        ?snapshotIndex.recordAt(seq),
    ];
    final bucket = _bucketOf(
      resolved,
      ledger: ledger,
      entryById: entryById,
      state: state,
      protectedTail: protectedTail,
      foldFromSeq: foldFromSeq,
      foldToSeq: foldToSeq,
      inRangeSeqs: inRangeSeqs,
      snapshotIndex: snapshotIndex,
    );
    counts[bucket] = counts[bucket]! + 1;
    if (bucket != HidePickBucket.snapped) continue;
    final group = <String>{
      for (final record in resolved) ...ledger.groupOf(record.id),
    };
    ids.addAll(group);
    final label = sanitizeHideLabel(pick.rawLabel);
    if (label != null) {
      labels.putIfAbsent(_carrierOf(group, snapshotIndex), () => label);
    }
  }
  return HandOverDisposeVerdict(
    recordIds: ids.toList()..sort(),
    labels: labels,
    counts: counts,
  );
}

HidePickBucket _bucketOf(
  List<SessionRecord> resolved, {
  required ContextLedger ledger,
  required Map<String, LedgerEntry> entryById,
  required StructuredViewState state,
  required Set<String> protectedTail,
  required int foldFromSeq,
  required int foldToSeq,
  required Set<int>? inRangeSeqs,
  required RecordSeqIndex snapshotIndex,
}) {
  if (resolved.isEmpty) return HidePickBucket.unknown;
  if (resolved.any(isFoldRecord)) return HidePickBucket.foldRecord;
  bool moot(SessionRecord record) {
    if (state.hiddenRecordIds.contains(record.id) ||
        state.isCovered(record.id)) {
      return true;
    }
    final seq = snapshotIndex.seqOf(record.id);
    if (seq == null) return false;
    return inRangeSeqs != null
        ? inRangeSeqs.contains(seq)
        : seq >= foldFromSeq && seq <= foldToSeq;
  }

  // The fresh ledger's `·exempt` (a real user turn); a record the ledger
  // does not list falls back to its own shape.
  bool isExempt(SessionRecord record) =>
      entryById[record.id]?.exempt ??
      (record is MessageRecord && record.message is UserMessage);

  final live = [
    for (final record in resolved)
      if (!moot(record)) record,
  ];
  if (live.isEmpty) return HidePickBucket.covered;
  if (live.any(isExempt)) {
    return HidePickBucket.exempt;
  }
  bool touchesTailOrPin(String id) =>
      protectedTail.contains(id) || state.pinnedRecordIds.contains(id);
  if (live.any((record) => touchesTailOrPin(record.id))) {
    return HidePickBucket.tail;
  }
  // Snap OUTWARD to the whole pair group (D6): a group that touches the
  // tail or a pin hides as a whole or never.
  for (final record in live) {
    for (final member in ledger.groupOf(record.id)) {
      if (touchesTailOrPin(member)) return HidePickBucket.tail;
    }
  }
  return HidePickBucket.snapped;
}

/// Whether [record] is a fold record (E28): its HIDE would render it
/// without a marker and unfold the range it replaces.
bool isFoldRecord(SessionRecord record) =>
    record is CompactCheckpointRecord ||
    record is CompactionRecord ||
    record is BranchSummaryRecord;

/// An alias no record can carry (file aliases are small counters) — the
/// sort key of a member missing from the snapshot index. A 30-bit
/// literal: dart2js shifts wrap at 32 (issue #1074 guard).
const int _beyondLastSeq = 1 << 30;

/// The group's carrier: the member with the smallest alias (file order).
String _carrierOf(Set<String> group, RecordSeqIndex snapshotIndex) {
  String? carrier;
  var carrierSeq = _beyondLastSeq;
  for (final id in group) {
    final seq = snapshotIndex.seqOf(id) ?? _beyondLastSeq;
    if (seq < carrierSeq) {
      carrierSeq = seq;
      carrier = id;
    }
  }
  return carrier ?? group.first;
}

/// The post-run soft trigger of the merged hand-over (GOAL #2394 D8/D9 —
/// AC11/AC12): the soft pressure line, the hysteresis that keeps a run
/// from firing on every turn of the `[soft, hard)` band, and the
/// `compacting` gate that queues a prompt arriving while the post-run
/// call is in flight. Pure Dart — hosts own the counters.
///
/// - PRE-FLIGHT stays hard-only (`shouldCompact` — over the line → fold
///   before the request); the hard guard is never suppressed.
/// - POST-RUN fires the soft line: the bucket the main request just
///   warmed is still hot, so the merged call reads it from cache.
/// - Hysteresis: after any compaction run the soft trigger stays
///   suppressed until pressure reaches the hard line or N user turns
///   passed (`compaction.handOver.hysteresisTurns`, default 3).
/// - No cache-miss latch: a cold bucket never changes the mode — it is
///   a report signal only.
library;

import 'dart:async';
import 'dart:math' show max;

import 'compaction.dart' show CompactionSettings, shouldCompact;

/// Default `compaction.handOver.hysteresisTurns`.
const int handOverHysteresisTurnsDefault = 3;

/// The soft line's default distance below the hard line, as a share of
/// the window (`softRatio` unset): hard − 5 % of the window.
const double softRatioDefaultGap = 0.05;

/// The soft trigger line in tokens: `floor(softRatio × window)` when the
/// key is set, else the hard line minus [softRatioDefaultGap] of the
/// window (never below 1).
int softTriggerTokens({
  required int window,
  required CompactionSettings settings,
  double? softRatio,
}) {
  if (softRatio != null) return max(1, (window * softRatio).floor());
  final hard = window - settings.reserveTokens;
  return max(1, hard - (window * softRatioDefaultGap).floor());
}

/// Whether the POST-RUN soft trigger fires for [tokens]: at or over the
/// soft line, and either over the hard line (pressure the hysteresis
/// never suppresses) or past the hysteresis window.
bool softTriggerReached({
  required int tokens,
  required int window,
  required CompactionSettings settings,
  double? softRatio,
  required HandOverHysteresis hysteresis,
}) {
  if (!settings.enabled) return false;
  if (tokens >=
      softTriggerTokens(
        window: window,
        settings: settings,
        softRatio: softRatio,
      )) {
    return shouldCompact(tokens, window, settings) || hysteresis.allowSoft;
  }
  return false;
}

/// The soft-trigger hysteresis (D8): counts user turns, remembers the
/// turn of the last compaction run.
final class HandOverHysteresis {
  /// Creates a hysteresis with the configured turn window.
  HandOverHysteresis({this.turns = handOverHysteresisTurnsDefault});

  /// User turns that must pass after a run before the soft line may
  /// fire again (`compaction.handOver.hysteresisTurns`). Writable so a
  /// host that re-resolves its settings per run (the Flutter app) can
  /// keep ONE counter across config flips.
  int turns;

  int _turns = 0;
  int _turnsAtRun = -1 << 30;

  /// A user turn started (hosts call it at every prompt).
  void onTurn() => _turns++;

  /// A compaction run happened (success or failure alike — the band
  /// must not re-fire every turn over a failing endpoint).
  void recordRun() => _turnsAtRun = _turns;

  /// Turns passed since the last run (saturating).
  int get turnsSinceRun => max(0, _turns - _turnsAtRun);

  /// Whether the soft line may fire: no run yet, or the window passed.
  bool get allowSoft => turnsSinceRun >= turns;
}

/// The host-side holder of the two stateful pieces (CLI and Flutter
/// alike): the hysteresis and the `compacting` gate. Pure state — the
/// host owns WHEN to call [softReached] (post-run only, AC11) and
/// [recordRun] (after any compaction run, success or failure alike).
final class HandOverTriggerState {
  /// Creates the state; [turns] is `compaction.handOver.hysteresisTurns`
  /// (null → the default).
  HandOverTriggerState({int? turns})
    : hysteresis = HandOverHysteresis(
        turns: turns ?? handOverHysteresisTurnsDefault,
      );

  /// The soft-trigger hysteresis.
  final HandOverHysteresis hysteresis;

  /// The `compacting` gate — one run at a time, prompts wait.
  final CompactingGate gate = CompactingGate();

  /// Applies `compaction.handOver.hysteresisTurns` (null → the default)
  /// to the ONE counter — a host that re-resolves its settings per run
  /// calls this before every [softReached].
  void tune({int? hysteresisTurns}) =>
      hysteresis.turns = hysteresisTurns ?? handOverHysteresisTurnsDefault;

  /// A user turn started (hosts call it at every user prompt).
  void onTurn() => hysteresis.onTurn();

  /// A compaction run happened.
  void recordRun() => hysteresis.recordRun();

  /// Whether the POST-RUN soft line fires for [tokens].
  bool softReached({
    required int tokens,
    required int window,
    required CompactionSettings settings,
    double? softRatio,
  }) => softTriggerReached(
    tokens: tokens,
    window: window,
    settings: settings,
    softRatio: softRatio,
    hysteresis: hysteresis,
  );
}

/// The `compacting` flag (D9 — E33): ONE compaction at a time, and a
/// prompt arriving while the post-run call is in flight WAITS for it
/// ([wait]) instead of racing a second `_refreshState` or losing a
/// persist. Not a lock on the prompt — the prompt's own pre-flight then
/// measures the fresh basis.
final class CompactingGate {
  Completer<void>? _active;

  /// Whether a compaction run is in flight.
  bool get isCompacting => _active != null;

  /// Runs [body] as THE compaction; a nested/second run while one is in
  /// flight is joined to the first's completion instead of starting
  /// (never two writers).
  Future<T> run<T>(Future<T> Function() body) async {
    final active = _active;
    if (active != null) {
      await active.future;
      return body();
    }
    final completer = Completer<void>();
    _active = completer;
    try {
      return await body();
    } finally {
      _active = null;
      completer.complete();
    }
  }

  /// Resolves when no compaction is in flight (immediately when idle).
  Future<void> wait() async {
    while (true) {
      final active = _active;
      if (active == null) return;
      await active.future;
    }
  }
}

