  /// context is rebuilt from the full view branch instead.
  Future<void> _growProviderContext(
    Session session,
    List<SessionRecord> delta,
  ) async {
    final hasCompaction = delta.any((r) => r is CompactionRecord);
    final branch = _viewBranch;
